class Nco {
    static constexpr int kLutBits = 12;
    std::array<std::complex<float>, (1u << kLutBits)> lut_;
    uint32_t phase_ = 0, ftw_ = 0;
public:
    Nco() {
        for (size_t i = 0; i < lut_.size(); ++i) {
            double th = 2.0 * M_PI * double(i) / double(lut_.size());
            lut_[i] = {float(std::cos(th)), float(std::sin(th))};
        }
    }
    // phase_ is not touched -> phase-continuous retune
    void setFreq(double f, double fs) {
        double r = f / fs;
        r -= std::floor(r);                       // negative f -> [0, 1)
        ftw_ = uint32_t(std::llround(r * 4294967296.0));  // mod 2^32
    }
    void mix(std::complex<float>* x, size_t n) {
        for (size_t i = 0; i < n; ++i) {
            x[i] *= lut_[phase_ >> (32 - kLutBits)];
            phase_ += ftw_;                       // wraps = 2*pi
        }
    }
};
